// Scanner turns the bytes of a source into tokens.
type Scanner struct {
	// source is the bytes being scanned.
	source []byte

	// filePath is the file path the scanner was given.
	filePath string

	// token is the current token.
	token Token

	// lexemeStartIdx is the index of the first byte of the current token.
	lexemeStartIdx int

	// lexemeEndIdx is the index one past the last byte of the current token.
	lexemeEndIdx int

	// lineStarts holds the byte offset every line of the source begins at. It is built on the first call to Position
	// and emptied by Reset, which keeps its storage for the next source.
	lineStarts []int
}

// NewScanner creates a scanner which turns the given bytes into tokens, starting at the first of them. The file path is
// used in error messages, so any string will do when the source is not a file.
func NewScanner(source []byte, filePath string) *Scanner {
	scanner := Scanner{
		filePath: filePath,
	}
	scanner.Reset(source, 0)
	return &scanner
}

// Token returns the current token.
func (s *Scanner) Token() Token {
	return s.token
}

// ByteOffset returns the start of the token in bytes from the start of the source. After Next returned false it is the
// offset one past the last byte.
func (s *Scanner) ByteOffset() int {
	return s.lexemeStartIdx
}

// ByteLength returns the length of the token in bytes. After Next returned false it is zero.
func (s *Scanner) ByteLength() int {
	return s.lexemeEndIdx - s.lexemeStartIdx
}

// Lexeme returns the bytes of the token, as a view into the source rather than a copy of it.
func (s *Scanner) Lexeme() []byte {
	return s.source[s.lexemeStartIdx:s.lexemeEndIdx]
}

// Position resolves a byte offset of the source into file path, line and column. Offsets from zero up to and including
// the length of the source are valid, the last of them being the end of the source, and an offset outside of that is
// clamped into it.
func (s *Scanner) Position(byteOffset int) Position {
	byteOffset = min(max(byteOffset, 0), len(s.source))

	if len(s.lineStarts) == 0 {
		s.buildLineStarts()
	}

	// The search returns where the offset would be inserted, which is the number of lines in front of it. An offset
	// which is a line start itself belongs to the line it starts.
	line, isLineStart := slices.BinarySearch(s.lineStarts, byteOffset)
	if isLineStart {
		line++
	}

	column := 1
	for _, value := range s.source[s.lineStarts[line-1]:byteOffset] {
		if value&0xc0 != 0x80 {
			column++
		}
	}
	return Position{
		FilePath:   s.filePath,
		ByteOffset: byteOffset,
		Line:       line,
		Column:     column,
	}
}

// buildLineStarts fills in the byte offset every line of the source begins at, into the storage left over from the
// source before. The first line begins at zero, so the result is never empty and an empty source has one line.
func (s *Scanner) buildLineStarts() {
	s.lineStarts = append(s.lineStarts, 0)
	for byteOffset := 0; byteOffset < len(s.source); {
		lineFeedIdx := bytes.IndexByte(s.source[byteOffset:], '\n')
		if lineFeedIdx < 0 {
			break
		}
		byteOffset += lineFeedIdx + 1
		s.lineStarts = append(s.lineStarts, byteOffset)
	}
}

// Text returns the bytes the given span covers, as a view into the source rather than a copy of it. The span is clamped
// to the source, and a negative length is empty.
func (s *Scanner) Text(byteOffset int, byteLength int) []byte {
	startIdx := min(max(byteOffset, 0), len(s.source))
	endIdx := min(max(startIdx, startIdx+byteLength), len(s.source))
	return s.source[startIdx:endIdx]
}

// FilePath returns the file path the scanner was given.
func (s *Scanner) FilePath() string {
	return s.filePath
}

// Reset scans the given source from the given byte offset on. Useful for re-tokenizing the part of a source which
// changed.
func (s *Scanner) Reset(source []byte, offset int) {
	s.source = source

	s.lexemeStartIdx = 0
	// An offset past the end of the source would point at bytes which are not there. Clamping it leaves the scanner
	// at the end of the source, where it reports the end token.
	s.lexemeEndIdx = min(offset, len(source))

	// The line starts belong to the source which was replaced here, but their storage is worth keeping.
	s.lineStarts = s.lineStarts[:0]

	s.token = InvalidToken
}

// Next advances to the next token. Bytes which form no token become an invalid token. Returns false once the end of the
// source is reached, which sets the token to the end token.
func (s *Scanner) Next() bool {
	s.lexemeStartIdx = s.lexemeEndIdx

	var state uint32
	lexemePeekIdx := s.lexemeEndIdx
	for {
		// Remember every accepting state passed through, so the longest match wins over the first one.
		if token := acceptTokenByState[state]; token != InvalidToken {
			s.token = token
			s.lexemeEndIdx = lexemePeekIdx
		}
		if lexemePeekIdx == len(s.source) {
			// The end of the source is reached, so the state it stopped in was the last one to test.
			break
		}

		byteClass := byteClassByByte[s.source[lexemePeekIdx]]
		cellIdx := uint32(transitionBase[state]) + uint32(byteClass)
		if transitionCheck[cellIdx] != byteClass {
			// The state has no transition on this byte, so the token ends here.
			break
		}
		state = uint32(transitionNext[cellIdx])
		lexemePeekIdx++
	}

	if s.lexemeStartIdx < s.lexemeEndIdx {
		// A token was found.
		return true
	}

	if len(s.source) <= s.lexemeStartIdx {
		// The end of the source was reached.
		s.token = EndToken
		return false
	}

	// The bytes here form no token. The invalid token ends where the automaton stopped, because the byte it could not
	// consume is where the next attempt starts. Only when the automaton consumed nothing does it cover that byte,
	// which is what keeps the scan moving forward.
	s.token = InvalidToken
	s.lexemeEndIdx = max(s.lexemeStartIdx+1, lexemePeekIdx)
	return true
}
